package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/reliant-labs/forge/internal/atomicfile"
	"github.com/reliant-labs/forge/internal/checksums"
	"github.com/reliant-labs/forge/internal/codegen"
	"github.com/reliant-labs/forge/internal/config"
)

// refreshFrontendRuntimeConfigs re-renders every frontend's runtime config
// document (config.js) from the environment's CURRENT KCL, and reports how
// many it actually changed.
//
// # The bug this closes
//
// One value in that document cannot be declared: an OIDC client's
// `client_id` is generated by the IdP when the application is registered.
// `forge env up` registers it (forge.ManagedIdentity) and writes the result
// to the env's secret store and .forge/identity/<name>.json.
//
// But config.js is rendered by `forge generate`, and the identity converges
// during `forge env up`. On a FRESH project those happen in that order exactly
// once, with the wrong result: generate renders the document before the client
// id exists, the converge then mints the real one, and nothing re-reads it. The browser gets `"OIDC_CLIENT_ID": ""` — which the frontend
// correctly interprets as the no-auth posture — and a first sign-in is
// impossible until the developer runs `forge generate` a second time, for
// a reason nothing on screen names.
//
// A second `forge generate` did fix it, which is what makes this the worst
// kind of bug: everything works for anyone who happens to regenerate, and
// nothing works for someone following the documented path.
//
// # Why re-render here rather than reorder generate
//
// The ordering cannot be fixed by moving generate. The client id does not
// exist until a running IdP has been asked for it, so no amount of
// rearranging generate-time steps can produce it — the value is only
// knowable AFTER the job, and the job needs a stack that is already up.
// This is a converge-then-publish dependency, and the honest shape for one
// is to re-read the published value once it exists.
//
// It re-renders the whole document rather than patching the one field on
// purpose: the document is a projection of the env's KCL, and rendering it
// through the same evaluator generate uses is what keeps this from becoming
// a second, subtly different opinion about what config.js should contain.
// Any other value the jobs converged rides along for free.
//
// It is a NO-OP when nothing changed, which is the normal case from the
// second run on — the identity is already published and the rendered bytes
// are identical, so the file is not rewritten and nothing is reported.
//
// Best-effort by design: this improves a document that already exists, so a
// render failure is reported and the dev loop continues. Blocking a `forge
// run` on it would trade a working stack with a stale client id for no
// stack at all.
//
// overlays is each frontend's render-resolved runtime_config (see
// frontendRuntimeOverlays); the caller has already rendered the env, so it
// passes them rather than this function rendering the whole env a second
// time. nil means none.
func refreshFrontendRuntimeConfigs(cfg *config.ProjectConfig, projectDir, envName string, overlays map[string]map[string]string) (int, error) {
	if cfg == nil || len(cfg.Frontends) == 0 {
		return 0, nil
	}
	docs, err := renderFrontendRuntimeDocsWith(projectDir, envName, overlays)
	if err != nil {
		return 0, fmt.Errorf("render frontend runtime config: %w", err)
	}
	return writeFrontendRuntimeDocs(cfg, projectDir, docs)
}

// writeFrontendRuntimeDocs writes each rendered document to the path its
// frontend actually serves it from, and reports how many CHANGED.
//
// Split from the render so the two halves are testable apart: rendering
// needs a project with a compiled proto descriptor, while the behaviour
// that was broken — a freshly published value not reaching the served file
// — is entirely in the writing. The render half's own property (that it
// reads the identity values the env declares) is covered by
// TestScaffoldedIdentityConfigKRenders.
func writeFrontendRuntimeDocs(cfg *config.ProjectConfig, projectDir string, docs map[string]string) (int, error) {
	if cfg == nil || len(cfg.Frontends) == 0 || len(docs) == 0 {
		return 0, nil
	}

	// The checksum ledger is loaded and saved around the writes so a file
	// forge owns stays stamped the way `forge generate` stamps it. Skipping
	// that would make the next generate see a Tier-1 file whose content it
	// did not record — i.e. report drift for a file forge itself wrote.
	cs, err := checksums.Load(projectDir)
	if err != nil {
		return 0, fmt.Errorf("load checksums: %w", err)
	}

	changed := 0
	for _, fe := range cfg.Frontends {
		body, ok := docs[fe.Name]
		if !ok {
			continue
		}
		staticDir := frontendStaticDir(fe.Type)
		if staticDir == "" {
			continue // react-native serves no static asset root
		}
		feDir, ok := fe.Dir(projectDir)
		if !ok {
			// No directory in this repository — a sibling checkout
			// (`../reliant/web`) or a cross-repo source pin. Its tree
			// belongs to another repo, so the document goes to this
			// project's own .forge/, where the dev server is pointed at
			// it (FORGE_RUNTIME_CONFIG_FILE, see outOfTreeRuntimeConfigRel).
			wrote, err := writeOutOfTreeRuntimeDoc(projectDir, fe.Name, body)
			if err != nil {
				return changed, err
			}
			if wrote {
				changed++
			}
			continue
		}
		// The frontend's code is in this tree, so public/config.js is the
		// document. An out-of-tree copy left from when it was not (the path
		// moved in) would otherwise keep shadowing it on the dev server.
		if err := os.Remove(filepath.Join(projectDir, outOfTreeRuntimeConfigRel(fe.Name))); err != nil && !os.IsNotExist(err) {
			return changed, fmt.Errorf("remove stale out-of-tree config.js for %s: %w", fe.Name, err)
		}
		rel := filepath.Join(feDir, staticDir, codegen.FrontendConfigJSFile)
		// Unchanged is the common case; comparing first keeps a no-op run
		// from touching the file's mtime, which a watching dev server would
		// otherwise treat as a reason to reload.
		//
		// Compared by BODY HASH, not by raw bytes. The file on disk carries
		// a `forge:hash=` stamp that the writer adds and this render does
		// not, so a byte comparison never matches and every single run
		// reports a change it did not make.
		if existing, rerr := os.ReadFile(filepath.Join(projectDir, rel)); rerr == nil &&
			checksums.BodyHash(existing) == checksums.BodyHash([]byte(body)) {
			continue
		}
		if err := os.MkdirAll(filepath.Join(projectDir, feDir, staticDir), 0o755); err != nil {
			return changed, fmt.Errorf("create static dir for %s: %w", fe.Name, err)
		}
		if _, err := checksums.WriteGeneratedFileTier1(projectDir, rel, []byte(body), cs, true); err != nil {
			return changed, fmt.Errorf("write config.js for %s: %w", fe.Name, err)
		}
		changed++
	}
	if changed > 0 {
		if err := checksums.Save(projectDir, cs); err != nil {
			return changed, fmt.Errorf("save checksums: %w", err)
		}
	}
	return changed, nil
}

// frontendRuntimeConfigFileEnv names the file a frontend's dev server serves
// as `config.js` instead of its own public/config.js. `forge env up` sets it
// for a frontend whose code is outside this project; the dev-server half is
// @reliantlabs/forge-web-runtime/vite's forgeRuntimeConfig plugin, which reads
// the same name.
const frontendRuntimeConfigFileEnv = "FORGE_RUNTIME_CONFIG_FILE"

// outOfTreeRuntimeConfigRel is where the runtime config document of a
// frontend whose code lives OUTSIDE this project is rendered, relative to
// the project root: .forge/runtime-config/<frontend>/config.js.
//
// The other repository's working tree is never written. Its public/ belongs
// to its own forge and its own git status, and a rendered environment there
// would be one repo's deploy values committed — or merely dirtying — another
// repo. The document is a projection of THIS project's env, so it lives in
// this project's state directory, and the frontend's dev server is told
// where it is.
func outOfTreeRuntimeConfigRel(frontend string) string {
	return filepath.Join(".forge", "runtime-config", frontend, codegen.FrontendConfigJSFile)
}

// writeOutOfTreeRuntimeDoc writes one out-of-tree document, reporting whether
// the bytes changed. It is not a Tier-1 file — nothing commits .forge/ — so
// it carries no checksum stamp and is compared verbatim.
func writeOutOfTreeRuntimeDoc(projectDir, frontend, body string) (bool, error) {
	path := filepath.Join(projectDir, outOfTreeRuntimeConfigRel(frontend))
	if existing, err := os.ReadFile(path); err == nil && string(existing) == body {
		return false, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return false, fmt.Errorf("create runtime-config dir for %s: %w", frontend, err)
	}
	if err := atomicfile.WriteFile(path, []byte(body), 0o644); err != nil {
		return false, fmt.Errorf("write out-of-tree config.js for %s: %w", frontend, err)
	}
	return true, nil
}

// outOfTreeRuntimeConfigFile is the absolute path of a frontend's out-of-tree
// document when one has been rendered, else "". A frontend whose code is in
// this tree never has one (writeFrontendRuntimeDocs removes a stale copy),
// so its dev server keeps serving public/config.js.
func outOfTreeRuntimeConfigFile(projectDir, frontend string) string {
	if projectDir == "" || frontend == "" {
		return ""
	}
	path := filepath.Join(projectDir, outOfTreeRuntimeConfigRel(frontend))
	if !filepath.IsAbs(path) {
		abs, err := filepath.Abs(path)
		if err != nil {
			return ""
		}
		path = abs
	}
	if info, err := os.Stat(path); err != nil || info.IsDir() {
		return ""
	}
	return path
}
